392	// ============================================================================
393	// HEALTH
394	// ============================================================================
395	
396	export interface AuthorityLayerHealth {
397	  /** External Gravito health */
398	  external: ReturnType<typeof getExternalGravitoHealth>;
399	  /** Authority layer metrics */
400	  metrics: Readonly<AuthorityMetrics>;
401	  /** Overall status */
402	  status: 'healthy' | 'degraded' | 'unavailable';
403	  /** Status reason */
404	  statusReason: string;
405	}
406	
407	export function getAuthorityLayerHealth(): AuthorityLayerHealth {
408	  const external = getExternalGravitoHealth();
409	  const metrics = getAuthorityMetrics();
410	  
411	  let status: AuthorityLayerHealth['status'] = 'healthy';
412	  let statusReason = 'All governance layers operational';
413	  
414	  if (!external.reachable && !external.mcpCliAvailable) {
415	    // Production mode — external not available, internal is authority
416	    status = 'degraded';
417	    statusReason = 'External Gravito unavailable (production mode). Internal governance is authority.';
418	  } else if (external.circuitBreakerState === 'open') {
419	    status = 'degraded';
420	    statusReason = `External Gravito circuit breaker OPEN (${external.consecutiveFailures} failures). Internal governance is authority.`;
421	  } else if (external.fallbackRate > 0.5) {
422	    status = 'degraded';
423	    statusReason = `External Gravito fallback rate ${(external.fallbackRate * 100).toFixed(1)}% > 50%. Internal governance supplementing.`;
424	  }
425	  
426	  return { external, metrics, status, statusReason };
427	}
