}

// ============================================================================
// HEALTH
// ============================================================================

export interface AuthorityLayerHealth {
  /** External Gravito health */
  external: ReturnType<typeof getExternalGravitoHealth>;
  /** Authority layer metrics */
  metrics: Readonly<AuthorityMetrics>;
  /** Overall status */
  status: 'healthy' | 'degraded' | 'unavailable';
  /** Status reason */
  statusReason: string;
}

export function getAuthorityLayerHealth(): AuthorityLayerHealth {
  const external = getExternalGravitoHealth();
  const metrics = getAuthorityMetrics();

  let status: AuthorityLayerHealth['status'] = 'healthy';
  let statusReason = 'All governance layers operational';

  if (!external.reachable && !external.mcpCliAvailable) {
    // Production mode — external not available, internal is authority
    status = 'degraded';
    statusReason = 'External Gravito unavailable (production mode). Internal governance is authority.';
  } else if (external.circuitBreakerState === 'open') {
    status = 'degraded';
    statusReason = `External Gravito circuit breaker OPEN (${external.consecutiveFailures} failures). Internal governance is authority.`;
  } else if (external.fallbackRate > 0.5) {
    status = 'degraded';
    statusReason = `External Gravito fallback rate ${(external.fallbackRate * 100).toFixed(1)}% > 50%. Internal governance supplementing.`;
  }

  return { external, metrics, status, statusReason };
}

// ============================================================================
// CONFIGURATION
// ============================================================================

export function updateAuthorityConfig(partial: Partial<AuthorityLayerConfig>): void {
  _config = { ..._config, ...partial };
}

export function getAuthorityConfig(): Readonly<AuthorityLayerConfig> {
  return { ..._config };
}

