      import('./governance-dashboard-router'),
    ]);

    // All functions exist
    expect(typeof requestApproval).toBe('function');
    expect(typeof getPreApprovalMetrics).toBe('function');
    expect(typeof getExternalTransportStatus).toBe('function');
    expect(typeof getTransportMetrics).toBe('function');
    expect(typeof getAuthorityMetrics).toBe('function');
    expect(typeof getAuthorityLayerHealth).toBe('function');
    expect(typeof getExternalGravitoHealth).toBe('function');
    expect(typeof getSyncWrapperMetrics).toBe('function');
    expect(governanceDashboardRouter).toBeDefined();

    // Regulated surfaces are populated
    expect(REGULATED_SURFACES.size).toBeGreaterThan(0);
  });

  it('should track pre-approval metrics after requestApproval call', async () => {
    const { requestApproval, getPreApprovalMetrics } = await import('./regulated-surface-preapproval');

    const metricsBefore = getPreApprovalMetrics();
    const requestedBefore = metricsBefore.preApprovalsRequested;

    await requestApproval({
      surfaceType: 'medical',
      contentHash: `integration-test-${Date.now()}`,
      correlationId: `integration-${Date.now()}`,
