// ============ Lead Stats Functions ============

export async function getLeadStats(): Promise<{
  total: number;
  byStatus: Record<string, number>;
  byTier: Record<string, number>;
  avgScore: number;
  todayCount: number;
}> {
  const db = await getDb();
  if (!db) {
    return { total: 0, byStatus: {}, byTier: {}, avgScore: 0, todayCount: 0 };
  }

  try {
    // Total count
    const totalResult = await db.select({ count: sql<number>`COUNT(*)` }).from(leads);
    const total = totalResult[0]?.count || 0;

    // By status
    const statusResult = await db.select({
      status: leads.status,
      count: sql<number>`COUNT(*)`
    }).from(leads).groupBy(leads.status);
    const byStatus: Record<string, number> = {};
    statusResult.forEach(r => { byStatus[r.status] = r.count; });

    // By tier
    const tierResult = await db.select({
      tier: leads.leadTier,
      count: sql<number>`COUNT(*)`
    }).from(leads).groupBy(leads.leadTier);
    const byTier: Record<string, number> = {};
    tierResult.forEach(r => { if (r.tier) byTier[r.tier] = r.count; });

    // Average score
    const avgResult = await db.select({
      avg: sql<number>`AVG(${leads.leadScore})`
    }).from(leads);
    const avgScore = Math.round(avgResult[0]?.avg || 0);

    // Today's count
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const todayResult = await db.select({ count: sql<number>`COUNT(*)` })
      .from(leads)
      .where(sql`${leads.createdAt} >= ${today}`);
    const todayCount = todayResult[0]?.count || 0;

    return { total, byStatus, byTier, avgScore, todayCount };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Leads] Error getting stats');
    return { total: 0, byStatus: {}, byTier: {}, avgScore: 0, todayCount: 0 };
  }
}


