    if (minAccuracy !== undefined && maxAccuracy !== undefined) {
      query = query.where(and(
        sql`${conversationSessions.accuracy} >= ${minAccuracy}`,
        sql`${conversationSessions.accuracy} <= ${maxAccuracy}`
      )) as typeof query;
    } else if (minAccuracy !== undefined) {
      query = query.where(sql`${conversationSessions.accuracy} >= ${minAccuracy}`) as typeof query;
    } else if (maxAccuracy !== undefined) {
      query = query.where(sql`${conversationSessions.accuracy} <= ${maxAccuracy}`) as typeof query;
    }

    return query.orderBy(conversationSessions.accuracy).limit(limit);
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[ConversationSession] Error fetching by accuracy');
    return [];
  }
}

