export async function recordGravitoReview(review: InsertGravitoReview): Promise<GravitoReview | null> {
  const db = await getDb();
  if (!db) return null;

  try {
    await db.insert(gravitoReviews).values(review);
    const [inserted] = await db
      .select()
      .from(gravitoReviews)
      .where(eq(gravitoReviews.proofId, review.proofId));

    const decision = review.decision;
    if (decision === "passed" || decision === "blocked" || decision === "warned") {
      await updateGravitoDailyStats(review.userId, decision);
    }

    return inserted || null;
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GravitoReview] Error recording review');
    return null;
  }
}

export async function updateGravitoDailyStats(
  userId: number, 
  decision: "passed" | "blocked" | "warned"
): Promise<void> {
  const db = await getDb();
  if (!db) return;

  try {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // Try to find existing stats for today
    const [existing] = await db
      .select()
      .from(gravitoUsageStats)
      .where(
        and(
          eq(gravitoUsageStats.userId, userId),
          sql`DATE(${gravitoUsageStats.date}) = DATE(${today})`
        )
      );

    if (existing) {
      // Update existing stats - use raw SQL for conditional increments
      const updateFields: Record<string, unknown> = {
        reviewsCount: sql`${gravitoUsageStats.reviewsCount} + 1`,
        proofsGenerated: sql`${gravitoUsageStats.proofsGenerated} + 1`,
      };

      if (decision === "passed") {
        updateFields.passedCount = sql`${gravitoUsageStats.passedCount} + 1`;
      }
      if (decision === "blocked") {
        updateFields.blockedCount = sql`${gravitoUsageStats.blockedCount} + 1`;
      }
      if (decision === "warned") {
        updateFields.warnedCount = sql`${gravitoUsageStats.warnedCount} + 1`;
      }

      await db
        .update(gravitoUsageStats)
        .set(updateFields)
        .where(eq(gravitoUsageStats.id, existing.id));
    } else {
      // Create new stats for today
      await db.insert(gravitoUsageStats).values({
        userId,
        date: today,
        reviewsCount: 1,
        passedCount: decision === "passed" ? 1 : 0,
        blockedCount: decision === "blocked" ? 1 : 0,
        warnedCount: decision === "warned" ? 1 : 0,
        proofsGenerated: 1,
      });
    }
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GravitoStats] Error updating daily stats');
  }
}

export async function getGravitoStats(userId: number, days: number = 30): Promise<{
  total: number;
  passed: number;
  blocked: number;
  warned: number;
  proofsGenerated: number;
  artifactsReviewed: number;
  gatesBlocked: number;
  lastRunAt: string | null;
  averageScore: number | null;
}> {
  const db = await getDb();
  if (!db) {
    return {
      total: 0,
      passed: 0,
      blocked: 0,
      warned: 0,
      proofsGenerated: 0,
      artifactsReviewed: 0,
      gatesBlocked: 0,
      lastRunAt: null,
      averageScore: null,
    };
  }

  try {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    // Get aggregated stats
    const [stats] = await db
      .select({
        total: sql<number>`COALESCE(SUM(${gravitoUsageStats.reviewsCount}), 0)`,
        passed: sql<number>`COALESCE(SUM(${gravitoUsageStats.passedCount}), 0)`,
        blocked: sql<number>`COALESCE(SUM(${gravitoUsageStats.blockedCount}), 0)`,
        warned: sql<number>`COALESCE(SUM(${gravitoUsageStats.warnedCount}), 0)`,
        proofsGenerated: sql<number>`COALESCE(SUM(${gravitoUsageStats.proofsGenerated}), 0)`,
      })
      .from(gravitoUsageStats)
      .where(
        and(
          eq(gravitoUsageStats.userId, userId),
          sql`${gravitoUsageStats.date} >= ${startDate}`
        )
      );

    // Get last review
    const [lastReview] = await db
      .select({
        createdAt: gravitoReviews.createdAt,
        score: gravitoReviews.score,
      })
      .from(gravitoReviews)
      .where(eq(gravitoReviews.userId, userId))
      .orderBy(desc(gravitoReviews.createdAt))
      .limit(1);

    // Get average score
    const [avgScore] = await db
      .select({
        avg: sql<number>`AVG(${gravitoReviews.score})`,
      })
      .from(gravitoReviews)
      .where(
        and(
          eq(gravitoReviews.userId, userId),
          sql`${gravitoReviews.createdAt} >= ${startDate}`
        )
      );

    return {
      total: Number(stats?.total || 0),
      passed: Number(stats?.passed || 0),
      blocked: Number(stats?.blocked || 0),
      warned: Number(stats?.warned || 0),
      proofsGenerated: Number(stats?.proofsGenerated || 0),
      artifactsReviewed: Number(stats?.total || 0),
      gatesBlocked: Number(stats?.blocked || 0),
      lastRunAt: lastReview?.createdAt 
        ? formatRelativeTime(lastReview.createdAt) 
        : null,
      averageScore: avgScore?.avg ? Math.round(Number(avgScore.avg)) : null,
    };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GravitoStats] Error getting stats');
    return {
      total: 0,
      passed: 0,
      blocked: 0,
      warned: 0,
      proofsGenerated: 0,
      artifactsReviewed: 0,
      gatesBlocked: 0,
      lastRunAt: null,
      averageScore: null,
    };
  }
}

function formatRelativeTime(date: Date): string {
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMins < 1) return "Just now";
  if (diffMins < 60) return `${diffMins} min ago`;
  if (diffHours < 24) return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
  if (diffDays < 7) return `${diffDays} day${diffDays > 1 ? 's' : ''} ago`;
  return date.toLocaleDateString();
}

