export async function getFeedbackStats(): Promise<{
  total: number;
  correct: number;
  incorrect: number;
  accuracy: number;
  byState: Record<string, { correct: number; incorrect: number }>;
  commonCorrections: Array<{ from: string; to: string; count: number }>;
}> {
  const db = await getDb();
  if (!db) {
    return { total: 0, correct: 0, incorrect: 0, accuracy: 0, byState: {}, commonCorrections: [] };
  }

  try {
    // Total counts
    const totalResult = await db.select({ count: sql<number>`COUNT(*)` }).from(benefitStateFeedback);
    const total = totalResult[0]?.count || 0;

    const correctResult = await db.select({ count: sql<number>`COUNT(*)` })
      .from(benefitStateFeedback)
      .where(eq(benefitStateFeedback.isCorrect, true));
    const correct = correctResult[0]?.count || 0;

    const incorrect = total - correct;
    const accuracy = total > 0 ? Math.round((correct / total) * 100) : 0;

    // By predicted state
    const byStateResult = await db.select({
      state: benefitStateFeedback.predictedState,
      isCorrect: benefitStateFeedback.isCorrect,
      count: sql<number>`COUNT(*)`
    })
      .from(benefitStateFeedback)
      .groupBy(benefitStateFeedback.predictedState, benefitStateFeedback.isCorrect);

    const byState: Record<string, { correct: number; incorrect: number }> = {};
    byStateResult.forEach(r => {
      if (!byState[r.state]) {
        byState[r.state] = { correct: 0, incorrect: 0 };
      }
      if (r.isCorrect) {
        byState[r.state].correct = r.count;
      } else {
        byState[r.state].incorrect = r.count;
      }
    });

    // Common corrections (from -> to)
    const correctionsResult = await db.select({
      from: benefitStateFeedback.predictedState,
      to: benefitStateFeedback.correctedState,
      count: sql<number>`COUNT(*)`
    })
      .from(benefitStateFeedback)
      .where(eq(benefitStateFeedback.isCorrect, false))
      .groupBy(benefitStateFeedback.predictedState, benefitStateFeedback.correctedState)
      .orderBy(sql`COUNT(*) DESC`)
      .limit(10);

    const commonCorrections = correctionsResult
      .filter(r => r.to)
      .map(r => ({ from: r.from, to: r.to!, count: r.count }));

    return { total, correct, incorrect, accuracy, byState, commonCorrections };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[BenefitStateFeedback] Error getting stats');
    return { total: 0, correct: 0, incorrect: 0, accuracy: 0, byState: {}, commonCorrections: [] };
  }
}

