export interface TurnInput {
  sessionId: string;
  turnNumber: number;
  role: 'user' | 'assistant';
  content: string;
  predictedState: string;
  correctedState?: string;
  confidence: number;
  signals?: Array<{ name: string; value: number; description: string }>;
  primitives?: Record<string, unknown>;
  previousState?: string;
  transitionReason?: string;
  timestamp: number;
}

export async function recordConversationTurn(data: TurnInput): Promise<number | null> {
  const db = await getDb();
  if (!db) return null;

  try {
    const turnData: InsertConversationTurn = {
      sessionId: data.sessionId,
      turnNumber: data.turnNumber,
      role: data.role,
      content: data.content,
      predictedState: data.predictedState,
      correctedState: data.correctedState,
      confidence: data.confidence,
      signals: data.signals ? JSON.stringify(data.signals) : null,
      primitives: data.primitives ? JSON.stringify(data.primitives) : null,
      previousState: data.previousState,
      transitionReason: data.transitionReason,
      timestamp: data.timestamp,
    };

    const [turnRow] = await db.insert(conversationTurns).values(turnData).returning({ id: conversationTurns.id });

    // Update session stats - use separate queries to avoid type issues
    await db.update(conversationSessions)
      .set({
        totalTurns: sql`${conversationSessions.totalTurns} + 1`,
      })
      .where(eq(conversationSessions.sessionId, data.sessionId));

    // Update correct/misprediction counts
    if (data.correctedState) {
      await db.update(conversationSessions)
        .set({
          mispredictions: sql`${conversationSessions.mispredictions} + 1`,
        })
        .where(eq(conversationSessions.sessionId, data.sessionId));
    } else {
      await db.update(conversationSessions)
        .set({
          correctPredictions: sql`${conversationSessions.correctPredictions} + 1`,
        })
        .where(eq(conversationSessions.sessionId, data.sessionId));
    }

    return turnRow?.id ?? null;
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[ConversationTurn] Error recording');
    return null;
  }
}

