  const [row] = await db.select().from(remediationRuns).where(eq(remediationRuns.runId, runId)).limit(1);
  return row;
}

export async function updateRemediationRunScore(runId: string, scoreAfter: number): Promise<void> {
  const db = await getDb();
  if (!db) return;
  await db.update(remediationRuns).set({ scoreAfter }).where(eq(remediationRuns.runId, runId));
}

// ============ Governed Surfaces Functions ============
// Database-backed surface registry for cross-surface governance

export async function upsertGovernedSurface(
  surfaceId: string,
  surfaceType: string,
  content: string,
  metadata?: Record<string, unknown>,
  orgId?: number
): Promise<void> {
  const db = await getDb();
  if (!db) {
    dbLog.warn({}, '[Database] Cannot upsert governed surface: database not available');
    return;
  }

  try {
    const contentHash = createHash('sha256').update(content).digest('hex');
    const values: InsertGovernedSurface = {
      surfaceId,
      surfaceType,
      orgId: orgId ?? null,
      contentSnapshot: content,
      contentHash,
      metadata: metadata ?? null,
      lastReviewedAt: new Date(),
    };

    await db.insert(governedSurfaces).values(values).onConflictDoUpdate({
      target: governedSurfaces.surfaceId,
      set: {
        contentSnapshot: content,
        contentHash,
        surfaceType,
        metadata: metadata ?? null,
        lastReviewedAt: new Date(),
      },
    });
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Database] Failed to upsert governed surface');
    throw error;
  }
}

export async function getGovernedSurface(surfaceId: string, orgId?: number): Promise<GovernedSurface | undefined> {
  const db = await getDb();
  if (!db) {
    dbLog.warn({}, '[Database] Cannot get governed surface: database not available');
    return undefined;
  }

  const conditions = [eq(governedSurfaces.surfaceId, surfaceId)];
  if (orgId !== undefined) {
    conditions.push(eq(governedSurfaces.orgId, orgId));
  }

  const result = await db.select().from(governedSurfaces).where(and(...conditions)).limit(1);
  return result.length > 0 ? result[0] : undefined;
}

export async function getAllGovernedSurfaces(orgId?: number): Promise<GovernedSurface[]> {
  const db = await getDb();
  if (!db) {
    dbLog.warn({}, '[Database] Cannot get all governed surfaces: database not available');
    return [];
  }

  const query = orgId !== undefined
    ? db.select().from(governedSurfaces).where(eq(governedSurfaces.orgId, orgId)).orderBy(desc(governedSurfaces.lastReviewedAt)).limit(1_000)
    : db.select().from(governedSurfaces).orderBy(desc(governedSurfaces.lastReviewedAt)).limit(1_000);

  return await query;
}

export async function getGovernedSurfacesByType(surfaceType: string, orgId?: number): Promise<GovernedSurface[]> {
  const db = await getDb();
  if (!db) {
    dbLog.warn({}, '[Database] Cannot get governed surfaces by type: database not available');
    return [];
  }

  const conditions = [eq(governedSurfaces.surfaceType, surfaceType)];
  if (orgId !== undefined) {
    conditions.push(eq(governedSurfaces.orgId, orgId));
  }

  return await db.select().from(governedSurfaces).where(and(...conditions)).orderBy(desc(governedSurfaces.lastReviewedAt)).limit(1_000);
}

export async function deleteGovernedSurface(surfaceId: string, orgId?: number): Promise<void> {
  const db = await getDb();
  if (!db) {
    dbLog.warn({}, '[Database] Cannot delete governed surface: database not available');
    return;
  }

  const conditions = [eq(governedSurfaces.surfaceId, surfaceId)];
  if (orgId !== undefined) {
    conditions.push(eq(governedSurfaces.orgId, orgId));
  }

  await db.delete(governedSurfaces).where(and(...conditions));
}

export async function updateGovernedSurfaceScore(
  surfaceId: string,
  score: number,
  violations: unknown[],
  orgId?: number
): Promise<void> {
  const db = await getDb();
  if (!db) return;

  const conditions = [eq(governedSurfaces.surfaceId, surfaceId)];
  if (orgId !== undefined) {
    conditions.push(eq(governedSurfaces.orgId, orgId));
  }

  await db.update(governedSurfaces).set({
    lastScore: score,
    lastViolations: violations,
  }).where(and(...conditions));
}


// ============ Governance Authority Audit — Phase 31B ============

/**
 * Persist a governance authority audit entry to the database.
 * Called non-blocking from the authority layer in callGravitoInline().
 * 
 * This is the database-backed audit trail that supplements the
 * in-memory ring buffer for long-term compliance and debugging.
 */
export async function persistAuthorityAudit(entry: {
  timestamp: number;
  surfaceType: string;
  regulated: boolean;
  externalAttempted: boolean;
  externalSuccess: boolean;
  externalSource: string;
  externalLatencyMs: number;
  internalLatencyMs: number;
  totalLatencyMs: number;
  mergeStrategy: string;
  authoritySource: string;
  finalScore: number;
  finalApproved: boolean;
  finalSeverity: string;
  issueCount: number;
  patchCount: number;
  gravitoRunId: string;
  retryCount: number;
  circuitBreakerState: string;
}): Promise<void> {
  const db = await getDb();
  if (!db) return;

  try {
    await db.insert(governanceAuthorityAudit).values({
      surfaceType: entry.surfaceType,
      regulated: entry.regulated,
      externalAttempted: entry.externalAttempted,
      externalSuccess: entry.externalSuccess,
      externalSource: entry.externalSource,
      externalLatencyMs: entry.externalLatencyMs,
      internalLatencyMs: entry.internalLatencyMs,
      totalLatencyMs: entry.totalLatencyMs,
      mergeStrategy: entry.mergeStrategy,
      authoritySource: entry.authoritySource,
      finalScore: entry.finalScore,
      finalApproved: entry.finalApproved,
      finalSeverity: entry.finalSeverity,
      issueCount: entry.issueCount,
      patchCount: entry.patchCount,
      gravitoRunId: entry.gravitoRunId,
      retryCount: entry.retryCount,
      circuitBreakerState: entry.circuitBreakerState,
      createdAt: entry.timestamp,
    });
  } catch (err) {
    dbLog.warn({ err }, '[GovernanceAudit] Failed to persist authority audit entry');
  }
}

/**
 * Query governance authority audit entries for analytics and debugging.
 */
export async function getAuthorityAuditEntries(options: {
  limit?: number;
  surfaceType?: string;
  regulated?: boolean;
  sinceTimestamp?: number;
} = {}): Promise<GovernanceAuthorityAuditRow[]> {
  const db = await getDb();
  if (!db) return [];

  const { limit = 100, surfaceType, regulated, sinceTimestamp } = options;

  try {
    const conditions: any[] = [];
    if (surfaceType) {
      conditions.push(eq(governanceAuthorityAudit.surfaceType, surfaceType));
    }
    if (regulated !== undefined) {
      conditions.push(eq(governanceAuthorityAudit.regulated, regulated));
    }
    if (sinceTimestamp) {
      conditions.push(gte(governanceAuthorityAudit.createdAt, sinceTimestamp));
    }

    const query = db.select().from(governanceAuthorityAudit);

    if (conditions.length > 0) {
      return await query.where(and(...conditions)).orderBy(desc(governanceAuthorityAudit.createdAt)).limit(limit);
    }

    return await query.orderBy(desc(governanceAuthorityAudit.createdAt)).limit(limit);
  } catch (err) {
    dbLog.warn({ err }, '[GovernanceAudit] Failed to query authority audit entries');
    return [];
  }
}

/**
 * Get authority audit summary statistics for dashboard.
 */
export async function getAuthorityAuditStats(days: number = 7): Promise<{
  totalDecisions: number;
  externalSuccessRate: number;
  avgLatencyMs: number;
  mergeStrategyCounts: Record<string, number>;
  regulatedDecisions: number;
  blockedDecisions: number;
}> {
  const db = await getDb();
  if (!db) {
    return {
      totalDecisions: 0,
      externalSuccessRate: 0,
      avgLatencyMs: 0,
      mergeStrategyCounts: {},
      regulatedDecisions: 0,
      blockedDecisions: 0,
    };
  }

  try {
    const sinceTimestamp = Date.now() - (days * 24 * 60 * 60 * 1000);
    const entries = await db.select().from(governanceAuthorityAudit)
      .where(gte(governanceAuthorityAudit.createdAt, sinceTimestamp));

    const total = entries.length;
    if (total === 0) {
      return {
        totalDecisions: 0,
        externalSuccessRate: 0,
        avgLatencyMs: 0,
        mergeStrategyCounts: {},
        regulatedDecisions: 0,
        blockedDecisions: 0,
      };
    }

    const externalAttempted = entries.filter(e => e.externalAttempted).length;
    const externalSucceeded = entries.filter(e => e.externalSuccess).length;
    const externalSuccessRate = externalAttempted > 0 ? externalSucceeded / externalAttempted : 0;

    const avgLatencyMs = Math.round(entries.reduce((sum, e) => sum + e.totalLatencyMs, 0) / total);

    const mergeStrategyCounts: Record<string, number> = {};
    for (const entry of entries) {
      mergeStrategyCounts[entry.mergeStrategy] = (mergeStrategyCounts[entry.mergeStrategy] || 0) + 1;
    }

    const regulatedDecisions = entries.filter(e => e.regulated).length;
    const blockedDecisions = entries.filter(e => !e.finalApproved).length;

    return {
      totalDecisions: total,
      externalSuccessRate,
      avgLatencyMs,
      mergeStrategyCounts,
      regulatedDecisions,
      blockedDecisions,
    };
  } catch (err) {
    dbLog.warn({ err }, '[GovernanceAudit] Failed to compute authority audit stats');
    return {
      totalDecisions: 0,
      externalSuccessRate: 0,
      avgLatencyMs: 0,
      mergeStrategyCounts: {},
      regulatedDecisions: 0,
      blockedDecisions: 0,
    };
  }
}

